func resetMCPPathEnv(t *testing.T) string {
	t.Helper()
	home := t.TempDir()
	t.Setenv("HOME", home)
	for _, name := range []string{
		"PELOTON_CONFIG",
		"PELOTON_CONFIG_DIR",
		"PELOTON_DATA_DIR",
		"PELOTON_STATE_DIR",
		"PELOTON_CACHE_DIR",
		"PELOTON_HOME",
		"XDG_CONFIG_HOME",
		"XDG_DATA_HOME",
		"XDG_STATE_HOME",
		"XDG_CACHE_HOME",
	} {
		t.Setenv(name, "")
	}
	restore, err := cliutil.SetHomeOverride("")
	if err != nil {
		t.Fatalf("reset home override: %v", err)
	}
	t.Cleanup(restore)
	return home
}

// stubMCPCLIAvailable deterministically simulates companion-CLI resolution
// succeeding or failing, overriding mcpCLIPathResolver for the test's
// duration. Without this, tests asserting on the store-missing/store-empty
// message would depend on whether a real "peloton-pp-cli" binary happens to
// resolve on whatever machine or CI runner executes `go test` -- it won't,
// during a normal `go test` run, since the test binary has no
// "peloton-pp-cli" sibling and PATH/PELOTON_CLI_PATH aren't set, but relying
// on that absence as if it were a deliberate test fixture would be fragile.
func stubMCPCLIAvailable(t *testing.T, available bool) {
	t.Helper()
	original := mcpCLIPathResolver
	if available {
		// mcpCompanionCLIAvailable now verifies the resolved path is
		// actually executable (exec.LookPath), not just present, so a
		// fabricated path like "/fake/peloton-pp-cli" would fail that
		// check and defeat this stub. os.Args[0] -- the running test
		// binary itself -- is a real, executable file guaranteed to exist
		// in every test environment.
		exe := os.Args[0]
		mcpCLIPathResolver = func() (string, error) { return exe, nil }
	} else {
		mcpCLIPathResolver = func() (string, error) { return "", fmt.Errorf("simulated: companion CLI not found") }
	}
	t.Cleanup(func() { mcpCLIPathResolver = original })
}

func TestMCPRegisterToolsPreservesTypedSpecialTools(t *testing.T) {
	s := server.NewMCPServer("peloton", "test")
	RegisterTools(s)

	tools := s.ListTools()
	if len(tools) == 0 {
		t.Fatal("RegisterTools registered no tools")
	}
	contextTool, ok := tools["context"]
	if !ok {
		t.Fatalf("typed context tool missing from registered tools: %#v", tools)
	}
	if !strings.Contains(contextTool.Tool.Description, "Get API domain context") {
		t.Fatalf("context tool appears to have been overwritten by command mirror: %q", contextTool.Tool.Description)
	}
	searchTool, ok := tools["search"]
	if !ok {
		t.Fatalf("typed search tool missing from registered tools: %#v", tools)
	}
	if !strings.Contains(searchTool.Tool.Description, "Full-text search across all synced data") {
		t.Fatalf("search tool appears to have been overwritten by command mirror: %q", searchTool.Tool.Description)
	}
	sqlTool, ok := tools["sql"]
	if !ok {
		t.Fatalf("typed sql tool missing from registered tools: %#v", tools)
	}
	if !strings.Contains(sqlTool.Tool.Description, "Run read-only SQL against local database") {
		t.Fatalf("sql tool appears to have been overwritten by command mirror: %q", sqlTool.Tool.Description)
	}
}

// TestHandleContextDescribesPelotonNotCRM guards against handleContext
// regressing to the generator's generic CRM template scaffolding (SIGNIFICANT
// #4 from a live post-fix verification sweep): the context tool is
// front-loaded domain knowledge agents read first, and it previously
// reported "archetype": "crm", a stale tool_count of 10 (actual is higher
// once framework/command-mirror tools are counted), a "resources" list
// missing "performance"/"workout_details" with no mention of sync/offline/
// doctor, and CRM-specific playbook entries ("Contact lookup", "CRM APIs
// often throttle activity-log endpoints heavily") that make no sense for a
// fitness API.
func TestHandleContextDescribesPelotonNotCRM(t *testing.T) {
	result, err := handleContext(context.Background(), mcplib.CallToolRequest{})
	if err != nil {
		t.Fatalf("handleContext returned transport error: %v", err)
	}
	if result == nil || result.IsError {
		t.Fatalf("handleContext IsError = %v, want false", result != nil && result.IsError)
	}
	text := mcpTextContent(t, result)

	var ctx map[string]any
	if err := json.Unmarshal([]byte(text), &ctx); err != nil {
		t.Fatalf("handleContext result is not valid JSON: %v\n%s", err, text)
	}

	if archetype, _ := ctx["archetype"].(string); archetype == "crm" {
		t.Fatalf("archetype = %q, want a peloton-accurate value, not the generic CRM template default", archetype)
	}

	toolCount, ok := ctx["tool_count"].(float64)
	if !ok || toolCount < 20 {
		t.Fatalf("tool_count = %v, want an accurate count reflecting all registered tools (endpoint + framework + command-mirror), not the stale template value of 10", ctx["tool_count"])
	}

	resources, ok := ctx["resources"].([]any)
	if !ok {
		t.Fatalf("resources = %#v, want an array", ctx["resources"])
	}
	names := map[string]bool{}
	for _, r := range resources {
		obj, ok := r.(map[string]any)
		if !ok {
			continue
		}
		if name, ok := obj["name"].(string); ok {
			names[name] = true
		}
	}
	for _, want := range []string{"performance", "workout_details"} {
		if !names[want] {
			t.Fatalf("resources missing %q entry: %#v", want, names)
		}
	}

	for _, forbidden := range []string{"crm", "CRM", "Contact lookup", "deal activity", "oauth2_refresh"} {
		if strings.Contains(text, forbidden) {
			t.Fatalf("handleContext result still contains stale CRM-template or OAuth-flavored text %q:\n%s", forbidden, text)
		}
	}

	for _, want := range []string{"sync", "offline", "doctor"} {
		if !strings.Contains(text, want) {
			t.Fatalf("handleContext result does not mention %q anywhere; agents reading this first won't discover it", want)
		}
	}
}

